"use client"

import {
  type ChangeEvent,
  type FocusEvent,
  forwardRef,
  type InputHTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  useId,
  useMemo,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../lib/hooks/use-controllable-state"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import { resolveFieldControl, useField } from "../field/field"
import {
  type InputGroupSize,
  inputGroupAddon,
  inputGroupButton,
  inputGroupControl,
  inputGroupVariants,
} from "../input-group/input-group"
import {
  CheckIcon,
  ChevronDownIcon,
  emptyClass,
  firstEnabled,
  listboxClass,
  optionCheckClass,
  optionClass,
  optionDescriptionClass,
  optionIconClass,
  optionLabelClass,
  optionTextClass,
  Highlight,
  matchesQuery,
  stepIndex,
  usePopup,
  useScrollActive,
  XIcon,
} from "./internal"
import { Layer } from "../lib/primitives/layer"

export interface ComboboxOption {
  value: string
  /** Plain text: shown, announced and matched against the query. */
  label: string
  description?: string
  icon?: ReactNode
  disabled?: boolean
}

export interface ComboboxProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "size" | "type" | "name"
> {
  options: readonly ComboboxOption[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  /** Called as the user types. */
  onInputChange?: (query: string) => void
  filter?: (option: ComboboxOption, query: string) => boolean
  size?: InputGroupSize
  invalid?: boolean
  /** Shows a clear button while a value is set. */
  clearable?: boolean
  clearLabel?: string
  emptyMessage?: ReactNode
  /** Decorative icon before the text. */
  leading?: ReactNode
  /** Submits the value through a hidden input. */
  name?: string
  onOpenChange?: (open: boolean) => void
}

const defaultFilter = (option: ComboboxOption, query: string) =>
  matchesQuery(option.label, query)

/**
 * An APG editable combobox with list autocomplete. Focus stays in the input; the active option
 * is conveyed with `aria-activedescendant`. The value is always one of the options.
 */
export const Combobox = forwardRef<HTMLInputElement, ComboboxProps>(
  (
    {
      options,
      value: valueProp,
      defaultValue = null,
      onValueChange,
      onInputChange,
      filter = defaultFilter,
      size = "md",
      invalid,
      disabled,
      required,
      clearable,
      clearLabel = "Clear",
      emptyMessage = "No results",
      leading,
      name,
      onOpenChange,
      placeholder,
      id,
      className,
      style,
      onKeyDown,
      onBlur,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
      ...props
    },
    forwardedRef,
  ) => {
    const control = resolveFieldControl(useField(), {
      id,
      disabled,
      required,
      invalid,
      "aria-describedby": describedBy,
      "aria-errormessage": errorMessage,
    })
    const [value, setValue] = useControllableState<string | null>({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const [open, setOpenState] = useState(false)
    const [query, setQuery] = useState<string | null>(null)
    const [active, setActive] = useState(-1)
    const groupRef = useRef<HTMLDivElement>(null)
    const inputRef = useRef<HTMLInputElement>(null)
    const ref = useComposedRefs(inputRef, forwardedRef)
    const baseId = useId()
    const inputId = control.id ?? `${baseId}-input`
    const listId = `${baseId}-listbox`
    const optionId = (index: number) => `${baseId}-option-${index}`

    const selected = options.find((option) => option.value === value)
    const typing = query !== null
    const items = useMemo(
      () =>
        typing && query.trim()
          ? options.filter((option) => filter(option, query))
          : options,
      [options, filter, query, typing],
    )

    const setOpen = (next: boolean) => {
      if (next === open) return
      setOpenState(next)
      onOpenChange?.(next)
    }
    const close = () => {
      setOpen(false)
      setQuery(null)
      setActive(-1)
    }
    const {
      ref: listRef,
      present,
      state,
    } = usePopup({
      open,
      anchorRef: groupRef,
      onDismiss: close,
    })
    useScrollActive(listRef, active, open)

    const openAt = (index: number) => {
      setActive(index)
      setOpen(true)
    }
    const commit = (option: ComboboxOption | undefined) => {
      if (option && !option.disabled) setValue(option.value)
      close()
    }

    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value
      setQuery(next)
      onInputChange?.(next)
      const filtered = next.trim()
        ? options.filter((option) => filter(option, next))
        : options
      openAt(next.trim() ? firstEnabled(filtered) : -1)
    }

    const handleKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented || control.disabled) return
      switch (event.key) {
        case "ArrowDown":
        case "ArrowUp": {
          event.preventDefault()
          const delta = event.key === "ArrowDown" ? 1 : -1
          if (!open) {
            const current = items.findIndex((option) => option.value === value)
            openAt(
              event.altKey ? -1 : current >= 0 ? current : stepIndex(items, -1, delta),
            )
          } else if (event.altKey && event.key === "ArrowUp") {
            commit(items[active])
          } else setActive((index) => stepIndex(items, index, delta))
          return
        }
        case "Enter":
          if (open) {
            event.preventDefault()
            if (active >= 0) commit(items[active])
            else close()
          }
          return
        case "Escape":
          if (open) {
            event.preventDefault()
            close()
          } else if (clearable && value !== null) {
            event.preventDefault()
            setValue(null)
          }
          return
      }
    }

    const handleBlur = (event: FocusEvent<HTMLInputElement>) => {
      onBlur?.(event)
      // Typing an option's exact label and leaving the field picks it, as people expect.
      if (typing) {
        const exact = options.find(
          (option) =>
            !option.disabled &&
            option.label.toLocaleLowerCase() === query.trim().toLocaleLowerCase(),
        )
        if (exact) setValue(exact.value)
        else if (!query.trim() && clearable) setValue(null)
      }
      close()
    }

    return (
      <>
        <div
          ref={groupRef}
          className={inputGroupVariants({
            size,
            end: "tight",
            className: cx("kg-combobox", className),
          })}
          style={style}
          data-size={size}
          data-state={open ? "open" : "closed"}
          data-invalid={control.invalid || undefined}
          data-disabled={control.disabled || undefined}
          onPointerDown={(event) => {
            if (event.target === groupRef.current) event.preventDefault()
            inputRef.current?.focus()
          }}
        >
          {(leading ?? selected?.icon) != null && (
            <span className={inputGroupAddon()} aria-hidden="true">
              {leading ?? selected?.icon}
            </span>
          )}
          <input
            ref={ref}
            id={inputId}
            type="text"
            role="combobox"
            autoComplete="off"
            aria-autocomplete="list"
            aria-expanded={open}
            aria-controls={present ? listId : undefined}
            aria-activedescendant={open && active >= 0 ? optionId(active) : undefined}
            aria-describedby={control.describedBy}
            aria-invalid={control.invalid || undefined}
            aria-errormessage={control.errorMessage}
            aria-required={control.required || undefined}
            disabled={control.disabled}
            placeholder={placeholder}
            className={inputGroupControl}
            value={typing ? query : (selected?.label ?? "")}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            onClick={() => {
              if (!open) openAt(items.findIndex((option) => option.value === value))
            }}
            {...props}
          />
          {clearable && value !== null && !control.disabled && (
            <button
              type="button"
              tabIndex={-1}
              className={inputGroupButton}
              aria-label={clearLabel}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => {
                setValue(null)
                inputRef.current?.focus()
              }}
            >
              <XIcon />
            </button>
          )}
          <button
            type="button"
            tabIndex={-1}
            aria-hidden="true"
            className={cx(
              inputGroupButton,
              "kg-combobox__toggle [&_svg]:transition-[rotate] [&_svg]:duration-(--kg-duration-base) [&_svg]:ease-kg-out",
              "[[data-state=open]>&_svg]:rotate-180",
            )}
            disabled={control.disabled}
            onMouseDown={(event) => event.preventDefault()}
            onClick={() => {
              inputRef.current?.focus()
              if (open) close()
              else openAt(items.findIndex((option) => option.value === value))
            }}
          >
            <ChevronDownIcon />
          </button>
        </div>
        {name !== undefined && <input type="hidden" name={name} value={value ?? ""} />}
        {present && (
          <Layer
            ref={listRef}
            id={listId}
            role="listbox"
            aria-labelledby={control.labelId}
            aria-label={control.labelId ? undefined : props["aria-label"]}
            className={listboxClass(size)}
            data-state={state}
            data-size={size}
            onMouseDown={(event) => event.preventDefault()}
          >
            {items.length === 0 ? (
              <div className={emptyClass} role="presentation">
                {emptyMessage}
              </div>
            ) : (
              items.map((option, index) => (
                <div
                  key={option.value}
                  id={optionId(index)}
                  role="option"
                  aria-selected={option.value === value}
                  aria-disabled={option.disabled || undefined}
                  data-active={index === active || undefined}
                  data-index={index}
                  className={optionClass}
                  onPointerMove={() => {
                    if (!option.disabled && active !== index) setActive(index)
                  }}
                  onClick={() => commit(option)}
                >
                  {option.icon != null && (
                    <span className={optionIconClass} aria-hidden="true">
                      {option.icon}
                    </span>
                  )}
                  <span className={optionTextClass}>
                    <span className={optionLabelClass}>
                      <Highlight text={option.label} query={query ?? ""} />
                    </span>
                    {option.description && (
                      <span className={optionDescriptionClass}>
                        {option.description}
                      </span>
                    )}
                  </span>
                  <span className={optionCheckClass} aria-hidden="true">
                    {option.value === value && <CheckIcon />}
                  </span>
                </div>
              ))
            )}
          </Layer>
        )}
        <span className="kg-visually-hidden" aria-live="polite">
          {open && typing
            ? `${items.length} ${items.length === 1 ? "result" : "results"}`
            : ""}
        </span>
      </>
    )
  },
)

Combobox.displayName = "Combobox"

"use client"

import { type ReactNode, type RefObject, useEffect } from "react"
import { useDismiss } from "../lib/hooks/use-dismiss"
import { type Side, useFloating } from "../lib/hooks/use-floating"
import { usePresence } from "../lib/hooks/use-presence"
import { cx } from "../lib/utils/cx"

/* Shared, unexported plumbing for the listbox-based pickers in this package. */

type ListSize = "sm" | "md" | "lg"

const listText: Record<ListSize, string> = {
  sm: "text-kg-sm",
  md: "text-kg-base",
  lg: "text-kg-md",
}

/* Paper Layers: the same sheet as Select's listbox, settling onto its offset as it opens. */
/** `panel` is a sheet with a header (search box, breadcrumb) above its own scrolling list. */
export const listboxClass = (size: ListSize = "md", kind: "list" | "panel" = "list") =>
  cx(
    "kg-combobox__listbox",
    kind === "list"
      ? "max-h-[min(18rem,calc(100dvh-2rem))] p-1 overflow-y-auto overscroll-contain"
      : "grid grid-rows-[auto_minmax(0,1fr)] max-h-[min(20rem,calc(100dvh-2rem))] p-0 overflow-hidden",
    "rounded-kg-lg border-2 border-kg-ink bg-kg-surface text-kg-fg shadow-kg-md",
    "origin-(--kg-origin,top_center) data-[side=bottom]:[--kg-enter-y:-4px] data-[side=top]:[--kg-enter-y:4px]",
    "data-[state=open]:animate-[kg-pop-in_var(--kg-duration-base)_var(--kg-ease-out)]",
    "data-[state=closed]:pointer-events-none data-[state=closed]:animate-[kg-pop-out_var(--kg-duration-fast)_var(--kg-ease-in)_forwards]",
    listText[size],
  )

export const optionClass = cx(
  "kg-combobox__option flex items-center gap-2.5 min-h-(--kg-control-sm) px-2.5 py-1.5 leading-[1.3]",
  "rounded-kg-sm cursor-default select-none transition-colors duration-(--kg-duration-fast) ease-kg-out",
  "data-active:bg-kg-muted aria-selected:font-semibold",
  "aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
)

export const optionIconClass =
  "kg-combobox__icon inline-grid place-items-center shrink-0 size-[1rem] text-kg-fg-muted [&_svg]:size-full [&_img]:size-full"

export const optionTextClass = "kg-combobox__text grid gap-[0.15em] flex-1 min-w-0"

export const optionLabelClass = "kg-combobox__label truncate"

export const optionDescriptionClass =
  "kg-combobox__description text-kg-xs font-normal text-kg-fg-muted"

export const optionCheckClass =
  "kg-combobox__check inline-grid place-items-center shrink-0 size-[1rem] text-kg-accent-strong [&_svg]:size-full"

export const emptyClass =
  "kg-combobox__empty px-3 py-4 text-kg-sm text-center text-kg-fg-muted"

const svg = {
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeLinecap: "round",
  strokeLinejoin: "round",
  "aria-hidden": true,
} as const

export const CheckIcon = () => (
  <svg {...svg} strokeWidth="2.5">
    <path d="M20 6 9 17l-5-5" />
  </svg>
)

export const ChevronDownIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="m6 9 6 6 6-6" />
  </svg>
)

export const ChevronRightIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="m9 6 6 6-6 6" />
  </svg>
)

export const ChevronLeftIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="m15 6-6 6 6 6" />
  </svg>
)

export const XIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
)

export const SearchIcon = () => (
  <svg {...svg} strokeWidth="2">
    <circle cx="11" cy="11" r="7" />
    <path d="m20 20-3.5-3.5" />
  </svg>
)

export const PlusIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="M12 5v14M5 12h14" />
  </svg>
)

export const MinusIcon = () => (
  <svg {...svg} strokeWidth="2">
    <path d="M5 12h14" />
  </svg>
)

export interface ListItemLike {
  label: string
  disabled?: boolean | undefined
}

export const matchesQuery = (label: string, query: string): boolean =>
  label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())

/** Next enabled index `delta` steps away, wrapping. Returns -1 when nothing is enabled. */
export const stepIndex = (
  items: readonly ListItemLike[],
  from: number,
  delta: 1 | -1,
): number => {
  const count = items.length
  if (count === 0) return -1
  let index = from < 0 ? (delta > 0 ? -1 : count) : from
  for (let tries = 0; tries < count; tries++) {
    index = (index + delta + count) % count
    if (!items[index]?.disabled) return index
  }
  return -1
}

export const firstEnabled = (items: readonly ListItemLike[]): number =>
  items.findIndex((item) => !item.disabled)

/** Wraps the first case-insensitive match of `query` in a <mark>. */
export const Highlight = ({
  text,
  query,
}: {
  text: string
  query: string
}): ReactNode => {
  const needle = query.trim().toLocaleLowerCase()
  const at = needle ? text.toLocaleLowerCase().indexOf(needle) : -1
  if (at < 0) return text
  return (
    <>
      {text.slice(0, at)}
      <mark className="kg-combobox__mark bg-transparent text-inherit font-bold underline decoration-kg-ink decoration-2 underline-offset-3">
        {text.slice(at, at + needle.length)}
      </mark>
      {text.slice(at + needle.length)}
    </>
  )
}

export interface PopupOptions {
  open: boolean
  anchorRef: RefObject<HTMLElement | null>
  onDismiss: () => void
  side?: Side
  matchWidth?: boolean
  align?: "start" | "center" | "end"
}

/** Presence, positioning and dismissal for a layer anchored to a field. */
export const usePopup = <T extends HTMLElement = HTMLDivElement>({
  open,
  anchorRef,
  onDismiss,
  side = "bottom",
  matchWidth = true,
  align = "start",
}: PopupOptions) => {
  const presence = usePresence<T>(open)
  useFloating(anchorRef, presence.ref, { open, side, align, offset: 6, matchWidth })
  useDismiss({ enabled: open, refs: [anchorRef, presence.ref], onDismiss })
  return presence
}

/** Keeps the active option visible by scrolling only the list, never the page. */
export const useScrollActive = (
  listRef: RefObject<HTMLElement | null>,
  active: number,
  open: boolean,
): void => {
  useEffect(() => {
    const list = listRef.current
    const option = list?.querySelector<HTMLElement>(`[data-index="${active}"]`)
    if (!open || !list || !option) return
    const top = option.offsetTop
    const bottom = top + option.offsetHeight
    if (top < list.scrollTop) list.scrollTop = top
    else if (bottom > list.scrollTop + list.clientHeight)
      list.scrollTop = bottom - list.clientHeight
  }, [listRef, active, open])
}

/**
 * A popup trigger is a button, so its label would hide the value it shows. Pointing
 * `aria-labelledby` at the label (or the button's own `aria-label`) and then the value keeps
 * both in the name: "Time zone, Tokyo".
 */
export const triggerLabelledBy = (options: {
  labelledBy: string | undefined
  labelId: string | undefined
  ariaLabel: string | undefined
  selfId: string
  valueId: string
  hasValue: boolean
}): string | undefined => {
  const { labelledBy, labelId, ariaLabel, selfId, valueId, hasValue } = options
  if (labelledBy) return labelledBy
  if (!hasValue) return undefined
  if (labelId) return `${labelId} ${valueId}`
  if (ariaLabel) return `${selfId} ${valueId}`
  return undefined
}
